#!/bin/sh
# Build the API 35 shared Bionic closure: libdl.so + libc.so.
#
# Android 15 specifics:
#   * the syscall stubs are generated by gensyscalls.py (genrule syscalls-arm64);
#   * libc.so owns the _Unwind_* exports (LIBC_R), provided by the LLVM libunwind
#     that AOSP keeps in external/llvm-project. That tree cannot be fetched as a
#     standalone archive, so the NDK's aarch64 libunwind.a (same implementation,
#     built for bionic) is linked whole-archive;
#   * the guest libraries are 16 KiB page aligned, so the runtime uses 16384.
set -eu
: "${MODULE:=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)}"
RT=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)
. "$RT/compile.sh"
UP="$RT/upstream"
B="$UP/bionic/libc"
OUT="$RT/build"
DERIVED="$OUT/derived"
mkdir -p "$OUT/obj/libc" "$OUT/obj/libdl" "$OUT/lib" "$OUT/generated"
test -f "$OUT/bin/source-linker64" || { echo "run build-linker.sh first" >&2; exit 1; }
test -f "$OUT/lib/liba15vm-bootstrap.a" || { echo "run build-static.sh first" >&2; exit 1; }
test -d "$DERIVED/bionic/libc/system_properties" || { echo "run build-static.sh first (derived)" >&2; exit 1; }

python3 "$RT/select-libc-sources.py" "$UP" shared > "$OUT/generated/libc-sources.txt"
python3 "$B/tools/gensyscalls.py" arm64 "$B/SYSCALLS.TXT" > "$OUT/generated/syscalls.S"
test -s "$OUT/generated/syscalls.S" || { echo "gensyscalls produced no output" >&2; exit 1; }
# Android 15 generates version scripts with generate-version-script from libc.map.txt.
if [ -f "$UP/bionic/tools/generate-version-script.py" ]; then
    python3 "$UP/bionic/tools/generate-version-script.py" arm64 "$B/libc.map.txt" "$OUT/generated/libc.map"
elif [ -f "$UP/bionic/tools/genversion-scripts.py" ]; then
    ANDROID_BUILD_TOP="$UP" python3 "$UP/bionic/tools/genversion-scripts.py"
    tr -d '\r' < "$B/libc.arm64.map" > "$OUT/generated/libc.map"
else
    echo "no version script generator found under bionic/libc/tools" >&2
    exit 1
fi
tr -d '\r' < "$B/libc.map.txt" > "$OUT/generated/libc.map.txt"
if [ -f "$UP/bionic/libdl/libdl.map.txt" ]; then
    # libdl.map.txt carries arch tags (dl_unwind_find_exidx is arm-only); the
    # generator drops the ones that do not apply to arm64.
    python3 "$UP/bionic/tools/generate-version-script.py" arm64 \
        "$UP/bionic/libdl/libdl.map.txt" "$OUT/generated/libdl.map"
else
    tr -d '\r' < "$UP/bionic/libdl/libdl.arm64.map" > "$OUT/generated/libdl.map"
fi

builtins=$(clang --target=aarch64-linux-android35 --print-libgcc-file-name)
test -f "$builtins"
unwind=$(ls "$NDK_TOOLCHAIN"/lib/clang/*/lib/linux/aarch64/libunwind.a 2>/dev/null | head -n 1)
if [ ! -f "$unwind" ]; then
    echo "missing NDK libunwind.a under $NDK_TOOLCHAIN/lib/clang" >&2
    exit 1
fi
# AOSP exports the unwinder from libc.so through libunwind-exported, whose
# symbols have default visibility. The NDK ships libunwind.a with hidden
# symbols (it is meant to be linked into executables), so the LIBC_R exports
# would stay hidden. Raise exactly the _Unwind_* visibility before linking;
# this is the same object code, only the ELF visibility changes.
exported_unwind="$OUT/lib/libunwind-exported.a"
if [ ! -f "$exported_unwind" ] || [ "$unwind" -nt "$exported_unwind" ]; then
    mkdir -p "$OUT/generated"
    llvm-nm --defined-only "$unwind" 2>/dev/null | awk '{print $NF}' \
        | grep '^_Unwind_' | sort -u > "$OUT/generated/unwind-symbols.txt"
    test -s "$OUT/generated/unwind-symbols.txt"
    ( cd "$OUT/generated" && llvm-objcopy \
        --set-symbols-visibility=unwind-symbols.txt=default \
        "$unwind" "$exported_unwind" )
fi

BUILD_KIND=shared
dl_objects=
for path in libdl.cpp libdl_cfi.cpp; do
    object="$OUT/obj/libdl/$path.o"
    compile "$UP/bionic/libdl/$path" "$object"
    dl_objects="$dl_objects $object"
done
ld.lld -shared -soname libdl.so -z max-page-size=$PAGE_SIZE -z now -z relro \
    --hash-style=gnu --eh-frame-hdr --build-id=sha1 --no-undefined --exclude-libs ALL \
    --version-script "$OUT/generated/libdl.map" $dl_objects "$OUT/bin/source-linker64" \
    "$builtins" -o "$OUT/lib/libdl.so"

objects=
. "$MODULE/vendor/runtime/filesystem/sources.sh"
while read -r path; do
    path=$(printf '%s' "$path" | tr -d '\r')
    [ -n "$path" ] || continue
    if guest_fs_replaces "$path"; then continue; fi
    case "$path" in
        bionic/libc/arch-arm64/syscalls/prctl.S) continue ;;
    esac
    object="$OUT/obj/libc/$(printf '%s' "$path" | tr / _).o"
    case "$path" in
        bionic/libc/system_properties/*|bionic/libc/bionic/system_property_api.cpp|bionic/libc/async_safe/async_safe_log.cpp)
            if [ -f "$DERIVED/bionic/libc/${path#bionic/libc/}" ]; then
                input="$DERIVED/bionic/libc/${path#bionic/libc/}"
            else input="$B/${path#bionic/libc/}"; fi ;;
        *) input="$UP/$path" ;;
    esac
    case "$path" in
        bionic/libc/arch-arm64/bionic/grp_pwd.cpp)
            compile "$input" "$object" -I"$PROPINC" -I"$OUT/generated" -I"$B/bionic" ;;
        bionic/libc/arch-arm64/bionic/syscall.S)
            compile "$input" "$object" -Dsyscall=a10vm_kernel_syscall ;;
        # The project owns these entry points (guest path mapping + host
        # fallbacks). Keep libc's implementations as host-side aliases, exactly
        # as A9 does for realpath.
        bionic/libc/bionic/realpath.cpp)
            compile "$input" "$object" -Drealpath=a10vm_host_realpath ;;
        bionic/libc/bionic/rename.cpp)
            compile "$input" "$object" -Drenameat=a10vm_host_renameat ;;
        # The derived (patched) copy is built at the end of this script.
        system/core/property_service/libpropertyinfoparser/property_info_parser.cpp)
            continue ;;
        *)
            if [ "${A15_FORCE:-0}" = 1 ] || [ ! -f "$object" ] || [ "$input" -nt "$object" ]; then
                compile "$input" "$object" -I"$PROPINC"
            fi ;;
    esac
    objects="$objects $object"
done < "$OUT/generated/libc-sources.txt"
# Project bridges first: they replace a subset of the generated syscall stubs.
vendor_objects=
for path in GuestPaths GuestFileCalls GuestProcMaps GuestExec GuestRealpath \
            GuestOwnership GuestIdentity GuestXattrs GuestTimers GuestSockets \
            GuestSandbox GuestSyscalls; do
    object="$OUT/obj/libc/$path.o"
    if [ "$path" = GuestSyscalls ]; then
        compile "$MODULE/vendor/runtime/filesystem/$path.cpp" "$object"
    else
        compile "$MODULE/vendor/runtime/filesystem/$path.cpp" "$object" -Dsyscall=a10vm_kernel_syscall
    fi
    objects="$objects $object"
    vendor_objects="$vendor_objects $object"
done
object="$OUT/obj/libc/GuestSyscalls.S.o"
compile "$MODULE/vendor/runtime/filesystem/GuestSyscalls.S" "$object"
objects="$objects $object"
vendor_objects="$vendor_objects $object"

# Generated syscall stubs (A15 genrule syscalls-arm64 equivalent), minus the
# names the bridges already define.
: > "$OUT/obj/libc/vendor-symbols.txt"
for object in $vendor_objects; do
    if command -v cygpath >/dev/null 2>&1; then nm_path=$(cygpath -w "$object"); else nm_path="$object"; fi
    llvm-nm -g --defined-only "$nm_path" 2>/dev/null | awk '{print $NF}' >> "$OUT/obj/libc/vendor-symbols.txt" || true
done
python3 "$RT/filter-syscalls.py" "$OUT/generated/syscalls.S" \
    "$OUT/obj/libc/vendor-symbols.txt" "$OUT/generated/syscalls-filtered.S"
object="$OUT/obj/libc/syscalls.S.o"
compile "$OUT/generated/syscalls-filtered.S" "$object" -Dsyscall=a10vm_kernel_syscall
objects="$objects $object"

# Guard against A15 renaming a generated stub again (A9/A10 `___faccessat` ->
# A15 `__faccessat`, `___fchmodat` -> `__fchmodat`). The filter above matches by
# symbol name, so a rename silently leaves the raw `svc` stub linked: the libc
# entry point then resolves the path on the HOST and the bridge is dead code
# with no error anywhere. These two must never survive.
for name in __faccessat __fchmodat renameat2 linkat; do
    if grep -q "ENTRY($name)" "$OUT/generated/syscalls-filtered.S"; then
        echo "guest path bridge ineffective: $name still uses the raw syscall stub" >&2
        exit 1
    fi
done
# Path-taking entry points that the bridges do not map yet. Kept as a visible
# list instead of a silent gap; see STATUS.md "known limitations".
# linkat/renameat2 moved out of this list on 2026-10-27 (D track): bionic routes
# rename()/renameat()/link() through them, so leaving them raw sent those calls
# to HOST paths and installd died with EACCES.
grep -o 'ENTRY([^)]*)' "$OUT/generated/syscalls-filtered.S" | sed 's/ENTRY(//;s/)//' \
    | grep -E '^(statx)$' > "$OUT/generated/unmapped-path-stubs.txt" || true

object="$OUT/obj/libc/property_info_parser.o"
compile "$DERIVED/core/property_service/libpropertyinfoparser/property_info_parser.cpp" "$object"
objects="$objects $object"
object="$OUT/obj/libc/allocator_stubs.o"
compile "$MODULE/vendor/runtime/libc_allocator_stubs.c" "$object"
objects="$objects $object"

# libc references ldexp (libm) and android_get_exported_namespace
# (libdl_android). AOSP links libc against both libraries; the API 35 guest
# copies come from the Redroid image, which was built for the same API level.
# They are link inputs here, so libc.so records the same DT_NEEDED entries as
# the image's own libc instead of hiding them behind local stubs.
GUEST_BIONIC="$MODULE/rootfs/apex/com.android.runtime/lib64/bionic"
GUEST_LIBM="$GUEST_BIONIC/libm.so"
GUEST_LIBDL_ANDROID="$GUEST_BIONIC/libdl_android.so"
test -f "$GUEST_LIBM" || { echo "missing guest libm.so for the libc link" >&2; exit 1; }
test -f "$GUEST_LIBDL_ANDROID" || { echo "missing guest libdl_android.so" >&2; exit 1; }

# Windows caps the command line at ~32K; a response file keeps the full object
# list. The native ld.lld.exe needs Windows paths.
: > "$OUT/obj/libc/objects.rsp"
for object in $objects; do
    if command -v cygpath >/dev/null 2>&1; then
        cygpath -w "$object" >> "$OUT/obj/libc/objects.rsp"
    else
        printf '%s\n' "$object" >> "$OUT/obj/libc/objects.rsp"
    fi
done
ld.lld -shared -soname libc.so -z max-page-size=$PAGE_SIZE -z now -z relro \
    --hash-style=gnu --eh-frame-hdr --build-id=sha1 --no-undefined \
    --exclude-libs libclang_rt.builtins-aarch64-android.a \
    --undefined-version \
    --version-script "$OUT/generated/libc.map" -Map "$OUT/libc.map" --error-limit=0 \
    "@$(cygpath -w "$OUT/obj/libc/objects.rsp" 2>/dev/null || printf '%s' "$OUT/obj/libc/objects.rsp")" \
    "$OUT/lib/libdl.so" "$OUT/bin/source-linker64" "$builtins" \
    "$GUEST_LIBM" "$GUEST_LIBDL_ANDROID" \
    "--whole-archive" "$exported_unwind" "--no-whole-archive" \
    -o "$OUT/lib/libc.so"
llvm-readelf -hlWd "$OUT/lib/libc.so" > "$OUT/libc-elf.txt"
llvm-nm -u "$OUT/lib/libc.so" > "$OUT/libc-undefined.txt"
llvm-readelf -hlWd "$OUT/lib/libdl.so" > "$OUT/libdl-elf.txt"
sha256sum "$OUT/lib/libc.so" "$OUT/lib/libdl.so" > "$OUT/shared-libraries.sha256"
echo "libc: $OUT/lib/libc.so"
echo "libdl: $OUT/lib/libdl.so"
